 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name sessionCheck
 * @description session Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sessionCheck = async function() {
    scwin.gUsrId = js_id;
    if (scwin.gUsrId === "" || scwin.gUsrId.length === 0) {
        await $c.win.alert("로그인 페이지로 이동합니다.");
        this.location.href = "/menu/login.jsp";

    }
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    scwin.gDepCd = js_dep_cd;
    // gEmpNo =  js_emp_no;
    scwin.gLdMktTp = js_market;
    scwin.gLdMktTp = js_market;
    // 유가 및 코스닥 종목을 동시에 보는 화면이므로 추가함.
    if (scwin.gLdMktTp === '1') {
        rdo_MKT_ID.setValue('9'); // 유가일때는 디폴트로  전체 셋팅

    } else {
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
    }

    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !기초자산공시--;
목록검색;
클릭-- > async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
