        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    let vRsnList = "";
    let vCnt = 0;
    if (chb_001.checked === true) {
        vRsnList = '001';
        vCnt++;
    }
    if (chb_016.checked === true) {
        if (vCnt > 0) {
            vRsnList += ',016';
        } else {
