    if (chb_027.checked === true) {
        if (vCnt > 0) {
            vRsnList += ',027';
        } else {
            vRsnList = '027';
        }
        vCnt++;
    }
    if (chb_031.checked === true) {
        if (vCnt > 0) {
            vRsnList += ',031';
        } else {
            vRsnList = '031';
        }
        vCnt++;
    }
    if (chb_013.checked === true) {
        if (vCnt > 0) {
            vRsnList += ',013';
