    if (chb_064.checked === true) {
        if (vCnt > 0) {
            vRsnList += ',064';
        } else {
            vRsnList = '064';
        }
        vCnt++;
    }

    // elw 공시사유분류 검색조건추가 end

    // 예외적으로 사유가 아닌 서식코드임
    if (chb_70764.checked === true) {
        scwin.gRsn70764YN = 'Y';
