        vCnt++;
    } else {
        scwin.gRsnExceptYN = 'N';
    }
    if (vCnt <= 0 && txb_FormNm.getValue() === '') {
        await $c.win.alert('한개이상 공시사유를 체크하시거나  공시제목을 입력하시기 바랍니다.');
